"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[8402],{83917(a,n,e){e.r(n),e.d(n,{assets:()=>s,contentTitle:()=>m,default:()=>d,frontMatter:()=>k,metadata:()=>i,toc:()=>r});const i=JSON.parse('{"id":"learning/courses/quantum-business-foundations/quantum-technology","title":"Teknologi Kuantum","description":"Kenali bahwa menyelesaikan masalah yang bermakna akan melibatkan kombinasi sumber daya kuantum dan klasik.","source":"@site/i18n/id/docusaurus-plugin-content-docs/current/learning/courses/quantum-business-foundations/quantum-technology.mdx","sourceDirName":"learning/courses/quantum-business-foundations","slug":"/learning/courses/quantum-business-foundations/quantum-technology","permalink":"/learning/courses/quantum-business-foundations/quantum-technology","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-business-foundations/quantum-technology.mdx","tags":[],"version":"current","frontMatter":{"title":"Teknologi Kuantum","description":"Kenali bahwa menyelesaikan masalah yang bermakna akan melibatkan kombinasi sumber daya kuantum dan klasik."},"sidebar":"tutorialsSidebar","previous":{"title":"Dasar-dasar komputasi kuantum","permalink":"/learning/courses/quantum-business-foundations/quantum-computing-fundamentals"},"next":{"title":"Dampak Bisnis","permalink":"/learning/courses/quantum-business-foundations/business-impacts"}}');var u=e(74848),t=e(28453);const k={title:"Teknologi Kuantum",description:"Kenali bahwa menyelesaikan masalah yang bermakna akan melibatkan kombinasi sumber daya kuantum dan klasik."},m="Teknologi IBM Quantum {#ibm-quantum-technology}",s={},r=[{value:"Tujuan pembelajaran",id:"learning-objectives",level:2},{value:"IBM Quantum Platform",id:"ibm-quantum-platform",level:3},{value:"Qiskit Runtime",id:"qiskit-runtime",level:3},{value:"Komputer kuantum superkonduktor IBM",id:"ibm-superconducting-quantum-computers",level:3},{value:"Kinerja komputasi kuantum",id:"quantum-computing-performance",level:2},{value:"Mengukur kinerja komputasi kuantum",id:"measuring-quantum-computing-performance",level:3},{value:"Cek pemahamanmu",id:"check-your-understanding",level:3},{value:"Apa selanjutnya dalam komputasi kuantum",id:"whats-next-in-quantum-computing",level:2},{value:"Quantum utility",id:"quantum-utility",level:3},{value:"Koreksi Kesalahan",id:"error-correction",level:3},{value:"Peta Jalan Pengembangan IBM Quantum",id:"ibm-quantum-development-roadmap",level:3},{value:"Tantangan 5k",id:"5k-challenge",level:3},{value:"Superkomputer berbasis kuantum",id:"quantum-centric-supercomputers",level:3},{value:"Poin-poin utama",id:"key-takeaways",level:2}];function l(a){const n={a:"a",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",img:"img",li:"li",p:"p",strong:"strong",ul:"ul",...(0,t.R)(),...a.components},{Accordion:i,AccordionItem:k,IBMVideo:m}=n;return i||g("Accordion",!0),k||g("AccordionItem",!0),m||g("IBMVideo",!0),(0,u.jsxs)(u.Fragment,{children:["\n","\n",(0,u.jsx)(n.header,{children:(0,u.jsx)(n.h1,{id:"ibm-quantum-technology",children:"Teknologi IBM Quantum"})}),"\n",(0,u.jsx)(n.p,{children:"Armada komputer kuantum IBM\xae, semuanya dengan setidaknya 127 qubit, adalah yang terbesar di dunia. Komputer kuantum ini menggunakan qubit transmon superkonduktor, yang bukan satu-satunya jenis qubit, tetapi memiliki banyak keunggulan. Menggabungkan komputer kuantum kelas dunia kami dengan Qiskit memungkinkan pengguna kami menjelajahi bagaimana komputasi kuantum bisa berguna di dunia, hari ini. Mitra industri dan peneliti menggunakan teknologi IBM Quantum\xae untuk mengeksplorasi komputasi yang bermakna dan aplikasi yang realistis. Mari jelajahi berbagai program dan layanan yang IBM Quantum tawarkan kepada mitra."}),"\n",(0,u.jsx)(n.p,{children:"Jika kamu adalah bagian dari institusi yang merupakan anggota IBM Quantum Network, pastikan untuk menghubungi grup komputasi kuantum institusimu untuk menentukan manfaat apa yang bisa kamu akses."}),"\n",(0,u.jsx)(n.h2,{id:"learning-objectives",children:"Tujuan pembelajaran"}),"\n",(0,u.jsx)(n.p,{children:"Di akhir modul ini, kamu seharusnya mampu:"}),"\n",(0,u.jsxs)(n.ul,{children:["\n",(0,u.jsx)(n.li,{children:"Mengenali bahwa menyelesaikan masalah yang bermakna akan melibatkan kombinasi sumber daya kuantum dan klasik."}),"\n",(0,u.jsx)(n.li,{children:"Mengidentifikasi perangkat keras, perangkat lunak, dan layanan yang tersedia untuk menyelesaikan masalah yang bermakna."}),"\n",(0,u.jsx)(n.li,{children:"Menjelaskan cara mengukur kinerja komputasi kuantum, termasuk skala, kualitas, dan kecepatan."}),"\n"]}),"\n",(0,u.jsx)(n.h3,{id:"ibm-quantum-platform",children:"IBM Quantum Platform"}),"\n",(0,u.jsx)(n.p,{children:"IBM Quantum Platform menyediakan rangkaian alat komputasi kuantum yang menyatukan semua sumber daya penelitian dan pengembangan yang dibutuhkan pengguna untuk bekerja dengan baik, dalam satu tempat. Pengguna bisa membuat akun dan masuk untuk mengakses komputer kuantum IBM, melihat detail komputer, melacak beban kerja, dan mengakses materi enablement di Dokumentasi dan Learning."}),"\n",(0,u.jsxs)(n.ul,{children:["\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.a,{href:"https://quantum.cloud.ibm.com/",children:"Halaman utama"})," berfungsi sebagai titik awal utama untuk ekosistem produk, di mana pengguna bisa mendapatkan kunci API mereka, melihat ringkasan instance dan informasi penggunaan mereka, melihat detail pekerjaan terbaru, dan mengakses tautan berguna ke tempat lain di seluruh platform."]}),"\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.a,{href:"/docs",children:"Dokumentasi"})," menggabungkan dokumentasi Qiskit, dokumentasi layanan, dan informasi referensi API ke dalam satu lokasi, diorganisir dengan cara yang mendukung alur kerja alami pengguna."]}),"\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.a,{href:"/learning",children:"Learning"})," adalah rumah bagi materi pendidikan termasuk kursus dan modul pengajaran, serta Circuit Composer interaktif (segera hadir). Kombinasi editor grafis dan kode ini memungkinkan pengguna membuat prototipe, mensimulasikan, dan men-debug Circuit secara visual, kemudian menjalankannya pada komputer kuantum IBM."]}),"\n"]}),"\n",(0,u.jsx)(n.h3,{id:"qiskit-runtime",children:"Qiskit Runtime"}),"\n",(0,u.jsx)(n.p,{children:"Qiskit Runtime adalah arsitektur yang portabel, aman, dan terkontainerisasi yang menjalankan program kuantum pada unit komputasi klasik yang terintegrasi erat dengan prosesor kuantum. Qiskit Runtime memungkinkan komputer kuantum menjadi bagian dari lingkungan komputasi apa pun untuk mempercepat komputasi \u2014 mirip dengan unit pemrosesan grafis (GPU) \u2014 dan menangani orkestrasi pekerjaan serta transfer data ke unit pemrosesan kuantum, memaksimalkan efisiensi."}),"\n",(0,u.jsx)(n.p,{children:"Qiskit dan Qiskit Runtime memudahkan untuk dengan cepat mengatur program di seluruh sumber daya komputasi di cloud. IBM membangun middleware untuk kuantum guna memaksimalkan kinerja aplikasi kuantum yang berjalan di seluruh sumber daya komputasi kuantum dan klasik yang diparalelkan dan berbasis cloud. Middleware ini mencakup circuit knitting toolbox dan arsitektur quantum serverless kami."}),"\n",(0,u.jsxs)(n.p,{children:[(0,u.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit-addon-cutting",children:"Qiskit addon pemotong Circuit"})," memungkinkan pengembang memotong Circuit besar menjadi Circuit yang lebih kecil yang cocok untuk komputer kuantum saat ini. Circuit knitting menggunakan komputasi klasik untuk mengambil sebagian beban komputasi dari Circuit kuantum untuk melampaui apa yang bisa kita capai dengan keduanya saja. Alat tambahan membantu merekonstruksi Circuit dengan sumber daya klasik dan menggabungkan hasil akhir."]}),"\n",(0,u.jsxs)(n.p,{children:[(0,u.jsx)(n.a,{href:"/guides/serverless",children:"Quantum Serverless"})," adalah toolkit orkestrasi multi-cloud untuk menghubungkan sumber daya klasik elastis dengan layanan IBM Qiskit Runtime. Quantum serverless memungkinkan pengembang fokus pada kode, bukan provisi sumber daya."]}),"\n",(0,u.jsx)(n.h3,{id:"ibm-superconducting-quantum-computers",children:"Komputer kuantum superkonduktor IBM"}),"\n",(0,u.jsxs)(n.p,{children:["Prosesor kuantum IBM menggunakan jenis fisik qubit yang disebut ",(0,u.jsx)(n.strong,{children:"qubit transmon superkonduktor"}),", yang terbuat dari material superkonduktor yang dipola di atas substrat silikon. Prosesor kuantum lain mungkin menggunakan qubit foton, yang terbuat dari foton tunggal cahaya, atau qubit ion terjebak, yang menyimpan informasi dalam partikel atom bermuatan. Untuk memfasilitasi aliran arus listrik, qubit superkonduktor perlu dipertahankan pada suhu yang sangat rendah \u2014 mendekati nol mutlak."]}),"\n",(0,u.jsx)(n.p,{children:(0,u.jsx)(n.img,{alt:"IBM 127-qubit processor",src:e(60794).A+"",width:"450",height:"450"})}),"\n",(0,u.jsx)(n.p,{children:(0,u.jsx)(n.em,{children:"Prosesor IBM 127-qubit"})}),"\n",(0,u.jsx)(n.h2,{id:"quantum-computing-performance",children:"Kinerja komputasi kuantum"}),"\n",(0,u.jsx)(n.h3,{id:"measuring-quantum-computing-performance",children:"Mengukur kinerja komputasi kuantum"}),"\n",(0,u.jsx)(n.p,{children:"Komputer kuantum toleran kesalahan universal adalah tantangan besar dari komputasi kuantum. Ini adalah perangkat yang dapat melakukan operasi kuantum universal dengan benar menggunakan komponen yang tidak dapat diandalkan. Komputer kuantum saat ini tidak toleran kesalahan."}),"\n",(0,u.jsx)(n.p,{children:"Untuk membandingkan komputer kuantum satu sama lain, jumlah qubit saja tidak cukup. Banyak detail lain harus dipertimbangkan, seperti tingkat kesalahan dan bagaimana sistem tersebut dihubungkan. Ada empat metrik utama untuk mengukur kinerja komputasi kuantum:"}),"\n",(0,u.jsxs)(n.ul,{children:["\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.strong,{children:"Skala"})," - Diukur dengan ",(0,u.jsx)(n.strong,{children:"jumlah qubit"}),", yang menunjukkan jumlah informasi yang bisa kita enkode dalam komputer kuantum."]}),"\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.strong,{children:"Kualitas"})," - Diukur dengan ",(0,u.jsx)(n.strong,{children:"Quantum Volume"}),", yang menunjukkan kualitas Circuit dan seberapa akurat Circuit diimplementasikan dalam perangkat keras."]}),"\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.strong,{children:"Kecepatan"})," - Diukur dengan ",(0,u.jsx)(n.strong,{children:"CLOPS (Circuit Layer Operations Per Second)"}),", yang menunjukkan berapa banyak Circuit yang bisa berjalan pada perangkat keras dalam waktu tertentu."]}),"\n",(0,u.jsxs)(n.li,{children:[(0,u.jsx)(n.strong,{children:"Layer Fidelity"})," - Diukur dengan ",(0,u.jsx)(n.strong,{children:"EPLG (Errors Per Layered Gate)"}),", yang menggambarkan bagaimana kesalahan terjadi ketika operasi dilakukan pada qubit."]}),"\n"]}),"\n",(0,u.jsxs)(n.p,{children:["Untuk deskripsi lebih rinci tentang beberapa metrik di atas, lihat ",(0,u.jsx)(n.a,{href:"https://www.ibm.com/quantum/blog/quantum-metric-layer-fidelity",children:"artikel ini"})," di IBM Research Blog. Setiap fase dalam adopsi komputasi kuantum di industri didorong oleh peningkatan Quantum Volume, yang dihitung menggunakan berbagai parameter seperti lebar Circuit, konektivitas qubit, dan tingkat kesalahan."]}),"\n",(0,u.jsx)(n.p,{children:"Definisi teknis Quantum Volume sulit dikomunikasikan tanpa persamaan.\nDario Gil, Direktur Penelitian di IBM, menjelaskan:"}),"\n",(0,u.jsx)(m,{id:"133345140",title:"Dario Gil explains the concept of quantum volume. In particular he explains how and why it depends on both qubit count and error rates."}),"\n",(0,u.jsx)(n.p,{children:"Untuk memahami Quantum Volume dengan lebih baik, pertimbangkan analogi menarik berikut. Bagian di bawah ini mencakup waktu, ruang, dan tingkat kesalahan dalam konteks wisata kota New York."}),"\n",(0,u.jsx)(n.p,{children:(0,u.jsx)(n.strong,{children:"Tur negara-negara Quantum Volume"})}),"\n",(0,u.jsxs)(n.p,{children:["Quantum Volume menggambarkan ruang komputasi kuantum terbesar yang dapat dijelajahi oleh komputer kuantum, di mana volume ruang kuantum adalah 2",(0,u.jsx)("sup",{children:"N"}),', dengan N adalah jumlah qubit, yaitu dimensi ruang keadaan biasa. Kita sengaja menggunakan kata "ruang" di sini karena begitu kita menyebut ruang, mudah untuk memikirkan sebuah volume.']}),"\n",(0,u.jsx)(n.p,{children:"Faktor yang membatasi eksplorasi ini adalah tingkat kesalahan. Tingkat kesalahan dapat disamakan dengan jumlah waktu yang diberikan kepada kita untuk mengeksplorasi ruang tersebut. Lebih banyak kesalahan berarti lebih sedikit waktu untuk mengeksplorasi. Semakin besar ruang komputasi yang kita miliki, semakin lama waktu yang dibutuhkan untuk menjelajahi ruang tersebut sepenuhnya, dan dengan demikian kita membutuhkan komputer kuantum dengan tingkat kesalahan yang lebih kecil."}),"\n",(0,u.jsx)(n.p,{children:"Pertimbangkan seorang turis yang menjelajahi Kota New York. Turis tersebut ingin menjelajahi seluruh kota, artinya turis tersebut menginginkan volume wisata seukuran NYC. Jika kita memberi turis hanya satu hari, maka tidak ada cara untuk menjelajahi begitu banyak ruang, sehingga turis tersebut tidak mendapatkan volume wisata yang diinginkan. Namun, jika kita memberi turis tiga hari, maka turis tersebut mungkin bisa mengunjungi semua tempat teratas dan mendapatkan volume wisata NYC yang dibutuhkan."}),"\n",(0,u.jsx)(n.p,{children:"Nah, bagaimana jika kita memberi turis lebih banyak waktu tetapi tetap membatasi ruang ke NYC? Dengan kata lain, bagaimana jika kita mempertahankan jumlah qubit tetapi mengurangi tingkat kesalahan? Maka tidak ada manfaat bagi turis karena turis sudah menjelajahi kota dan hanya mengunjungi tempat yang sama berulang kali. Volume wisata tetap sama. Sebaliknya, dengan lebih banyak waktu, lebih cerdas bagi turis untuk memperluas jumlah tempat wisata yang dikunjungi."}),"\n",(0,u.jsx)(n.p,{children:"Atau, misalkan kita mempertahankan waktu tiga hari tetapi turis memutuskan untuk mencoba menjelajahi seluruh NYC dan Long Island? Dengan kata lain, bagaimana jika kita memperbaiki tingkat kesalahan tetapi menambahkan lebih banyak qubit? Sekali lagi, volume wisata tetap seperti NYC karena turis tidak dapat menjelajahi ruang yang lebih besar dalam waktu yang diberikan. Dengan demikian, menjadi turis yang lebih baik, dan mencapai volume wisata yang lebih besar, memerlukan peningkatan secara bersamaan baik ruang wisata maupun jumlah waktu yang diperbolehkan bagi turis untuk menjelajahi."}),"\n",(0,u.jsx)(n.p,{children:"Dengan cara yang persis sama, membangun komputer kuantum yang lebih baik yang mencapai Quantum Volume lebih besar memerlukan peningkatan secara bersamaan ruang komputasi kuantum (jumlah qubit) sambil mengurangi tingkat kesalahan (meningkatkan jumlah waktu yang bisa dijalankan algoritma). Misalnya, melalui kemajuan dalam arsitektur kopling yang dapat diatur, IBM menggandakan quantum volume dua kali hanya dalam satu tahun!"}),"\n",(0,u.jsx)(n.p,{children:(0,u.jsx)(n.img,{src:"/learning/images/courses/quantum-business-foundations/quantum-technology/QV.avif",alt:"Quantum Volume"})}),"\n",(0,u.jsx)(n.p,{children:"Namun, seiring berkembangnya komputasi kuantum, kita mulai lebih peduli tentang pekerjaan berguna yang bisa dilakukan komputer kuantum kita dalam waktu yang wajar. Jika kita mengukur skala dengan jumlah qubit, dan kualitas dengan quantum volume, maka kecepatan pemrosesan kuantum adalah ukuran pekerjaan berguna yang bisa dilakukan qubit tersebut dalam waktu yang wajar. Kita mendefinisikannya sebagai jumlah Circuit primitif yang bisa diproses dalam satu detik. Ini mirip dengan FLOPS dalam komputasi klasik \u2014 jumlah operasi floating point per detik. Meningkatkan kecepatan QPU adalah kunci untuk komputasi kuantum yang praktis. Seperti pemrograman komputer klasik, pemrograman kuantum memerlukan menjalankan banyak Circuit. Kecepatan QPU yang wajar akan memungkinkan pengguna memasukkan komputasi kuantum sebagai bagian dari alur kerja mereka."}),"\n",(0,u.jsx)(n.h3,{id:"check-your-understanding",children:"Cek pemahamanmu"}),"\n",(0,u.jsx)(n.p,{children:"Benar atau salah: Quantum Volume mengacu pada ukuran kulkas kriogenik yang menampung komputer kuantum IBM."}),"\n",(0,u.jsx)(i,{children:(0,u.jsx)(k,{title:"Jawaban",children:(0,u.jsx)(n.p,{children:"Salah. Quantum Volume adalah satu angka yang dimaksudkan untuk merangkum kinerja komputer kuantum saat ini."})})}),"\n",(0,u.jsx)(n.h2,{id:"whats-next-in-quantum-computing",children:"Apa selanjutnya dalam komputasi kuantum"}),"\n",(0,u.jsx)(n.p,{children:"Komputer kuantum saat ini, dan yang diperkirakan untuk masa mendatang, bersifat noisy. Ini berarti mereka sensitif terhadap gangguan lingkungan yang dapat memengaruhi fidelitas hasil. Sama seperti komputasi klasik yang berkembang melalui penskalaan modular prosesor, komputasi yang efisien, dan paralelisasi, kita melihat komputasi kuantum berkembang untuk mewujudkan potensi penuhnya. Saat kita bekerja menuju komputer kuantum yang sepenuhnya toleran kesalahan, kita ingin menyelesaikan masalah yang berguna dengan perangkat keras dan perangkat lunak yang kita miliki saat ini."}),"\n",(0,u.jsx)(n.h3,{id:"quantum-utility",children:"Quantum utility"}),"\n",(0,u.jsx)(n.p,{children:"IBM Quantum dan University of California, Berkeley menyajikan bukti bahwa komputer kuantum dapat memberikan nilai lebih cepat dari yang diperkirakan berkat kemajuan dalam perangkat keras IBM Quantum dan metode mitigasi kesalahan. Bukan hanya sekadar bukti konsep, kami menghadirkan hasil yang cukup akurat untuk berguna. Model komputasi yang kami eksplorasi dengan pekerjaan ini merupakan aspek inti dari banyak algoritma yang dirancang untuk komputer kuantum jangka dekat."}),"\n",(0,u.jsx)(n.p,{children:"Loop umpan balik antara kuantum dan klasik adalah kunci untuk memajukan teknologi kuantum. Dengan fokus pada quantum utility, kita menggunakan kuantum untuk menyelidiki masalah kompleks yang menantang kerangka komputasi berkinerja tinggi yang ada, kemudian memeriksa hasilnya secara klasik. Bolak-balik berkelanjutan antara kuantum yang menjalankan Circuit kompleks dan komputer klasik yang memverifikasi hasil kuantum ini akan meningkatkan kedua domain komputasi dan memberikan pengguna kepercayaan pada kemampuan komputer kuantum jangka dekat."}),"\n",(0,u.jsx)(m,{id:"134056420",title:"This video outlines how noisy quantum computers use error mitigation to out-perform brute force classical methods on an example problem."}),"\n",(0,u.jsx)(i,{children:(0,u.jsx)(k,{title:"Bacaan opsional \u2014 klik segitiga untuk membaca lebih lanjut tentang eksperimen",children:(0,u.jsxs)(n.ul,{children:["\n",(0,u.jsxs)(n.li,{children:["\n",(0,u.jsx)(n.p,{children:"Dalam eksperimen ini, kami menggunakan semua 127 qubit dari prosesor IBM Quantum Eagle kami untuk mensimulasikan perilaku yang berubah dari sistem yang secara alami dipetakan ke komputer kuantum, yang disebut model Ising kuantum. Model Ising adalah penyederhanaan alam yang merepresentasikan atom-atom yang berinteraksi sebagai kisi sistem dua-pilihan kuantum yang berinteraksi dalam medan energi. Sistem ini terlihat sangat mirip dengan qubit dua-keadaan yang membentuk komputer kuantum kami, menjadikannya cocok untuk menguji kemampuan metode kami. Kami menggunakan ZNE untuk mencoba menghitung secara akurat properti sistem yang disebut nilai ekspektasi \u2014 pada dasarnya rata-rata berbobot dari kemungkinan hasil Circuit."}),"\n"]}),"\n",(0,u.jsxs)(n.li,{children:["\n",(0,u.jsx)(n.p,{children:"Secara bersamaan, tim Berkeley mencoba mensimulasikan sistem yang sama menggunakan metode jaringan tensor dengan bantuan superkomputer canggih yang berlokasi di Lawrence Berkeley National Lab's National Energy Research Scientific Computing Center (NERSC) dan di Purdue University."}),"\n"]}),"\n",(0,u.jsxs)(n.li,{children:["\n",(0,u.jsx)(n.p,{children:"Metode kuantum terus bersepakat dengan metode eksak. Tetapi akhirnya, metode aproksimasi klasik mulai goyah saat kesulitan ditingkatkan."}),"\n"]}),"\n",(0,u.jsxs)(n.li,{children:["\n",(0,u.jsx)(n.p,{children:"Akhirnya, kami meminta kedua komputer untuk menjalankan perhitungan di luar apa yang bisa dihitung secara eksak \u2014 dan komputer kuantum mengembalikan jawaban yang lebih kami yakini kebenarannya. Dan meskipun kami tidak dapat membuktikan apakah jawaban itu sebenarnya benar, keberhasilan Eagle pada percobaan sebelumnya memberi kami keyakinan bahwa mereka benar."}),"\n"]}),"\n"]})})}),"\n",(0,u.jsx)(n.h3,{id:"error-correction",children:"Koreksi Kesalahan"}),"\n",(0,u.jsx)(n.p,{children:"Koreksi kesalahan telah menjadi area penelitian utama selama beberapa dekade. Tetapi untuk sebagian besar waktu itu, teknik koreksi kesalahan teoritis tidak praktis untuk diimplementasikan pada komputer kuantum nyata, paling sering karena jumlah qubit yang sangat besar yang diperlukan. Memang, banyak ahli memprediksi bahwa komputasi kuantum toleran kesalahan praktis (FTQC) akan memerlukan jutaan qubit fisik. Tetapi dalam makalah terbaru yang diterbitkan di sampul Nature, peneliti dari IBM memperkenalkan kode baru, yang kami sebut kode Gross, yang mengatasi keterbatasan tersebut."}),"\n",(0,u.jsxs)(n.p,{children:["Makalah ",(0,u.jsx)(n.a,{href:"https://www.nature.com/articles/s41586-024-07107-7",children:"High-threshold and low-overhead fault-tolerant quantum memory"})," mendeskripsikan kode koreksi kesalahan kuantum baru yang sekitar 10 kali lebih efisien dari metode sebelumnya dalam melindungi data kuantum yang rapuh dari akumulasi kesalahan. Untuk mempertimbangkan seberapa dekat kita sekarang dari awal koreksi kesalahan, pertimbangkan bahwa menggunakan kode Gross, kamu bisa melindungi 12 qubit logis selama sekitar satu juta siklus pemeriksaan kesalahan menggunakan 288 qubit."]}),"\n",(0,u.jsx)(n.p,{children:"Tidak diharapkan bahwa koreksi kesalahan akan tiba-tiba menggantikan mitigasi kesalahan dan penekanan kesalahan. Sebaliknya, selama beberapa tahun ke depan, mitigasi kesalahan dan penekanan akan terus memainkan peran penting, bersama dengan semakin banyaknya qubit terkoreksi kesalahan."}),"\n",(0,u.jsx)(n.h3,{id:"ibm-quantum-development-roadmap",children:"Peta Jalan Pengembangan IBM Quantum"}),"\n",(0,u.jsx)(n.p,{children:"Kini kita berada dengan kuat di era quantum utility. Artinya komputer kuantum lebih baik dalam komputasi kuantum dari komputer klasik, dan bisa dimanfaatkan oleh pengguna kami untuk menemukan algoritma baru dan mencari quantum advantage. Peta jalan kami menguraikan tonggak-tonggak bersejarah dan rencana kami untuk mencapai quantum advantage jangka dekat pada tahun 2026."}),"\n",(0,u.jsxs)(n.p,{children:["Pada tahun 2029, kami akan menghadirkan Starling \u2014 komputer kuantum toleran kesalahan skala besar yang mampu menjalankan Circuit kuantum yang terdiri dari 100 juta Gate kuantum pada 200 qubit logis. Kami sedang membangun sistem ini sekarang di fasilitas bersejarah kami di Poughkeepsie, New York. Pelajari lebih lanjut tentang kemajuan kami dalam ",(0,u.jsx)(n.a,{href:"http://www.ibm.com/downloads/documents/us-en/131cf87ab63319bf",children:"Guided Roadmap PDF."})]}),"\n",(0,u.jsx)(n.p,{children:(0,u.jsx)(n.img,{alt:"Development Roadmap",src:e(80305).A+"",width:"1920",height:"1080"})}),"\n",(0,u.jsxs)(n.p,{children:["Baca lebih lanjut tentang peta jalan pengembangan IBM Quantum ",(0,u.jsx)(n.a,{href:"https://www.ibm.com/quantum/roadmap",children:"di sini"}),"."]}),"\n",(0,u.jsx)(n.h3,{id:"5k-challenge",children:"Tantangan 5k"}),"\n",(0,u.jsx)(n.p,{children:'IBM bekerja sama dengan komunitas penelitian kuantum untuk menemukan potensi kasus penggunaan yang bisa mendapat manfaat dari komputasi kuantum. Kami menyediakan alat yang semakin kuat sehingga pengguna bisa mengeksplorasi masalah mendesak dengan kuantum. Pada tahun 2024, kami merilis alat yang mampu menghitung observabel yang tidak bias dari Circuit panjang berkualitas tinggi. Menemukan apa yang bisa dilakukan dengan kombinasi 100+ qubit dan Circuit yang dalam pada suatu waktu disebut "tantangan 100x100". Tetapi jumlah qubit dan kedalaman yang tepat pada masing-masing kurang penting daripada memanfaatkan kekuatan kombinasi. Bayangkan apa yang mungkin dengan 5.000 Circuit kuantum dalam satu komputasi. Pengguna bisa menjalankan Circuit kuantum dengan kompleksitas dan runtime di luar kemampuan komputer klasik terbaik saat ini. Kami sangat antusias melihat apa yang akan dibangun komunitas kuantum untuk membantu kami memanfaatkan kekuatan kuantum dan menyelesaikan masalah penting.'}),"\n",(0,u.jsx)(n.h3,{id:"quantum-centric-supercomputers",children:"Superkomputer berbasis kuantum"}),"\n",(0,u.jsx)(n.p,{children:"Melampaui prosesor chip tunggal adalah kunci untuk menyelesaikan masalah pada skala. Pada tahun 2024, kami memperkenalkan Crossbill, prosesor tunggal pertama yang dibuat dari beberapa chip. Ini adalah langkah pertama menuju era penskalaan baru, memberikan jalur yang jelas menuju 100.000 qubit dan lebih banyak lagi dengan superkomputing berbasis kuantum. Ini adalah arsitektur komputasi modular yang memungkinkan penskalaan. Ini menggabungkan komunikasi dan komputasi kuantum untuk meningkatkan kapasitas komputasi, sambil menggunakan middleware hybrid cloud untuk mengintegrasikan alur kerja kuantum dan klasik secara mulus."}),"\n",(0,u.jsx)(n.p,{children:"Menyelesaikan masalah paling kompleks di dunia akan memerlukan kombinasi sumber daya klasik dan kuantum. Selanjutnya, ini akan bergantung pada kolaborasi berkelanjutan antara industri dan akademia."}),"\n",(0,u.jsx)(n.h2,{id:"key-takeaways",children:"Poin-poin utama"}),"\n",(0,u.jsx)(n.p,{children:"Kamu bisa mengingat poin-poin utama ini:"}),"\n",(0,u.jsxs)(n.ul,{children:["\n",(0,u.jsx)(n.li,{children:"Komputer kuantum saat ini tidak toleran kesalahan."}),"\n",(0,u.jsx)(n.li,{children:"Quantum Volume adalah ukuran holistik tentang seberapa baik komputer kuantum. Semakin tinggi Quantum Volume, semakin baik. Berbicara hanya tentang jumlah qubit adalah menyesatkan."}),"\n",(0,u.jsx)(n.li,{children:"Untuk mengukur kinerja komputer kuantum, ada empat metrik utama: skala, kualitas, kecepatan, dan layer fidelity."}),"\n",(0,u.jsx)(n.li,{children:"Eksperimen bersama IBM Quantum-UC Berkeley menyajikan bukti komputer kuantum IBM memberikan hasil yang andal dan akurat untuk masalah simulasi yang menantang pada skala 127 qubit."}),"\n",(0,u.jsx)(n.li,{children:"Superkomputing berbasis kuantum berarti memperlakukan kuantum sebagai satu bagian dari paradigma HPC yang lebih luas dengan klasik dan kuantum yang bekerja sebagai satu unit komputasi."}),"\n"]})]})}function d(a={}){const{wrapper:n}={...(0,t.R)(),...a.components};return n?(0,u.jsx)(n,{...a,children:(0,u.jsx)(l,{...a})}):l(a)}function g(a,n){throw new Error("Expected "+(n?"component":"object")+" `"+a+"` to be defined: you likely forgot to import, pass, or provide it.")}},60794(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/127qubit-processer-5f4e07dd161a5396ac24b1af43f9999a.avif"},80305(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/IBM-Quantum-Development-and-Innovation-Roadmap-2025-f5804f9bec56cfc9744c8755f6d3a0a5.svg"},28453(a,n,e){e.d(n,{R:()=>k,x:()=>m});var i=e(96540);const u={},t=i.createContext(u);function k(a){const n=i.useContext(t);return i.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function m(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(u):a.components||u:k(a.components),i.createElement(t.Provider,{value:n},a.children)}}}]);